function validate([h, w, horizontalCuts, verticalCuts]) {
  if (!Number.isInteger(h) || h < 2 || h > 1000000000) return 'h is an integer from 2 to 10^9.';
  if (!Number.isInteger(w) || w < 2 || w > 1000000000) return 'w is an integer from 2 to 10^9.';
  const check = (cuts, size, name, side) => {
    if (!Array.isArray(cuts) || cuts.length < 1 || cuts.length > Math.min(size - 1, 100000)) return `${name} needs 1 to min(${side} - 1, 10^5) cuts.`;
    if (cuts.some(v => !Number.isInteger(v) || v < 1 || v >= size)) return `Each value of ${name} is an integer from 1 to ${side} - 1.`;
    if (new Set(cuts).size !== cuts.length) return `The values of ${name} must be distinct.`;
    return null;
  };
  return check(horizontalCuts, h, 'horizontalCuts', 'h') ?? check(verticalCuts, w, 'verticalCuts', 'w');
}

