function maxArea(h, w, horizontalCuts, verticalCuts) {
  // Each strip runs from a boundary to the nearest larger boundary; no sorting.
  const strips = (cuts, size) => {
    const starts = [0, ...cuts];
    const ends = [...cuts, size];
    return starts.map(start => Math.min(...ends.filter(end => end > start)) - start);
  };
  let best = 0n;
  for (const height of strips(horizontalCuts, h)) {
    for (const width of strips(verticalCuts, w)) {
      const area = BigInt(height) * BigInt(width);
      if (area > best) best = area;
    }
  }
  return Number(best % 1000000007n);
}

