function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const cutsFor = (length, count) => {
    const seen = new Set();
    if (count >= length - 1) {
      for (let v = 1; v < length; v++) seen.add(v);
    } else {
      while (seen.size < count) seen.add(pick(1, length - 1));
    }
    const cuts = [...seen];
    for (let i = cuts.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [cuts[i], cuts[j]] = [cuts[j], cuts[i]];
    }
    return cuts;
  };
  const side = () => {
    if (size === 'small') {
      const length = rand() < 0.2 ? pick(999999990, 1000000000) : pick(2, 12);
      return [length, cutsFor(length, pick(1, Math.min(length - 1, 6)))];
    }
    const mode = Math.floor(rand() * 3);
    if (mode === 0) {
      const length = pick(900000000, 1000000000);
      return [length, cutsFor(length, pick(1000, 2000))];
    }
    if (mode === 1) {
      const length = pick(1000000, 1000000000);
      return [length, cutsFor(length, pick(1, 3))];
    }
    const length = pick(2000, 2001);
    return [length, cutsFor(length, pick(1500, length - 1))];
  };
  const [h, horizontalCuts] = side();
  const [w, verticalCuts] = side();
  return [h, w, horizontalCuts, verticalCuts];
}
